 const[method,setMethod]=useState("email"),[phone,setPhone]=useState(""),[email,setEmail]=useState(""),[password,setPassword]=useState(""),[msg,setMsg]=useState(""),[busy,setBusy]=useState(false);
 const[authChecking,setAuthChecking]=useState(true);
 useEffect(()=>{let active=true;const finish=async session=>{if(!active||!session)return;try{const{data:existing,error:profileError}=await supabase.rpc("my_customer_profile");if(profileError)throw profileError;if(!existing){const user=session.user,m=user.user_metadata||{},fullName=String(m.full_name||m.name||[m.given_name||m.first_name,m.family_name||m.last_name].filter(Boolean).join(" ")||user.email?.split("@")[0]||"Customer").trim(),parts=fullName.split(/\\s+/);const{error}=await supabase.from("customers").upsert({auth_user_id:user.id,name:fullName,first_name:m.given_name||m.first_name||parts[0]||"",last_name:m.family_name||m.last_name||parts.slice(1).join(""),email:user.email||m.email||null,phone:m.phone||"",address:m.address||null,city:m.city||null,district:m.district||null,province:m.province||null,postal_code:m.postal_code||null,is_active:true},{onConflict:"auth_user_id"});if(error)throw error;}if(active)location.replace(returnTo)}catch(error){if(active){setMsg("Signed in, but your customer profile could not be prepared. "+(error?.message||"Please contact support."));setAuthChecking(false)}}};const{data:listener}=supabase.auth.onAuthStateChange((_event,session)=>{if(session)void finish(session)});supabase.auth.getSession().then(({data,error})=>{if(!active)return;if(!error&&data.session){void finish(data.session);return}setAuthChecking(false)});return()=>{active=false;listener.subscription.unsubscribe()}},[]);
 const returnTo=(()=>{const value=new URLSearchParams(location.search).get("return");return value&&value.startsWith("/")&&!value.startsWith("//")?value:"/"})();
 if(authChecking)return <AuthLayout title="Customer Login"><p className="auth-intro">Checking your sign-in status…</p></AuthLayout>;
