async function offerPasskeyPrompt(userId){
 if(!userId)return;
 const key="suru-passkey-prompt:"+userId;
 if(localStorage.getItem(key)==="dismissed"||localStorage.getItem(key)==="enabled")return;
 return new Promise(resolve=>{
  const overlay=document.createElement("div");
  overlay.className="passkey-prompt-overlay";
  overlay.innerHTML='<section class="passkey-prompt" role="dialog" aria-modal="true" aria-labelledby="passkey-prompt-title"><button class="passkey-prompt-close" type="button" aria-label="Close">×</button><div class="passkey-prompt-icon" aria-hidden="true"><i class="fa-solid fa-fingerprint"></i></div><h2 id="passkey-prompt-title">Set Up Your Passkey</h2><p>Make your next login faster and more secure with Face ID, Touch ID, your device PIN, or a password manager.</p><button class="btn passkey-prompt-setup" type="button">Set Up Passkey</button><button class="passkey-prompt-later" type="button">Maybe Later</button><p class="passkey-prompt-status" aria-live="polite"></p></section>';
  document.body.appendChild(overlay);
  const close=()=>{overlay.remove();resolve()};
  const later=()=>{localStorage.setItem(key,"dismissed");close()};
  overlay.querySelector(".passkey-prompt-close").addEventListener("click",later);
  overlay.querySelector(".passkey-prompt-later").addEventListener("click",later);
  overlay.addEventListener("click",e=>{if(e.target===overlay)later()});
  overlay.querySelector(".passkey-prompt-setup").addEventListener("click",async e=>{
   const button=e.currentTarget,status=overlay.querySelector(".passkey-prompt-status");
   button.disabled=true;status.textContent="Starting secure passkey setup…";
   try{const{error}=await supabase.auth.registerPasskey();if(error)throw error;localStorage.setItem(key,"enabled");status.textContent="Passkey added successfully.";button.textContent="Done";button.disabled=false;button.onclick=close;overlay.querySelector(".passkey-prompt-later").hidden=true}
   catch(err){status.textContent=err?.message||"Passkey setup was not completed. You can add one later from My Account.";button.disabled=false;status.classList.add("is-error")}
  });
 });
}
function normalizeNepalPhone(value){
 const raw=String(value||"").trim().replace(/[\s()-]/g,"");
 if(raw.startsWith("+977"))return raw;
 if(raw.startsWith("977"))return "+"+raw;
 if(raw.startsWith("0"))return "+977"+raw.slice(1);
 return "+977"+raw;
}
function Register(){
 const[verifyMethod,setVerifyMethod]=useState("email"),[f,setF]=useState({first_name:"",last_name:"",email:"",password:"",confirm:"",phone:"",address:"",city:"",district:"",province:"",postal_code:""}),[msg,setMsg]=useState(""),[busy,setBusy]=useState(false),[otp,setOtp]=useState(""),[otpStep,setOtpStep]=useState(false),[registeredPhone,setRegisteredPhone]=useState(""),[pendingUser,setPendingUser]=useState(null);
 async function googleSignIn(){setBusy(true);setMsg("Redirecting to Google account creation…");const{error}=await supabase.auth.signInWithOAuth({provider:"google",options:{redirectTo:location.origin+"/login/?return=%2Faccount%2F"}});if(error){setMsg(error.message||"Google sign-up could not be started.");setBusy(false)}}
 const change=e=>{const{name,value}=e.target;if(name==="province")setF({...f,province:value,district:""});else if(name==="phone")setF({...f,phone:value.replace(/\D/g,"").slice(0,10)});else setF({...f,[name]:value});};
 async function createAccount(e){
   e.preventDefault();
   if(!f.first_name.trim()||!f.last_name.trim()||!f.address.trim()||!f.city.trim()||!f.district.trim()||!f.province.trim())return setMsg("Please fill in all required fields.");
   if(verifyMethod==="email"&&!f.email.trim())return setMsg("Enter an email address to receive your verification code.");
   if(!f.phone.trim())return setMsg("Enter your mobile number.");
   if(f.password.length<6)return setMsg("Password must be at least 6 characters.");
   if(f.password!==f.confirm)return setMsg("Passwords do not match.");
   const phone=f.phone.trim()?normalizeNepalPhone(f.phone):"";
   if(!/^\+9779\d{9}$/.test(phone))return setMsg("Please enter a valid Nepal mobile number.");
   setBusy(true);setMsg("Creating your account and sending OTP…");
   const metadata={name:(f.first_name.trim()+" "+f.last_name.trim()).trim(),first_name:f.first_name.trim(),last_name:f.last_name.trim(),email:f.email.trim().toLowerCase()||null,phone:phone||null,address:f.address.trim(),city:f.city.trim(),district:f.district.trim(),province:f.province.trim(),postal_code:f.postal_code.trim()||null};
   const result=verifyMethod==="mobile"
     ?await supabase.auth.signUp({phone,password:f.password,options:{channel:"whatsapp",data:metadata}})
     :await supabase.auth.signUp({email:f.email.trim().toLowerCase(),password:f.password,options:{data:metadata}});
   const{data,error}=result;
   if(error){setMsg(error.message);setBusy(false);return}
   if(!data?.user){setMsg("Unable to start registration. Please try again.");setBusy(false);return}
   setRegisteredPhone(phone);setPendingUser(data.user);setOtp("");setOtpStep(true);
   setMsg(verifyMethod==="mobile"?"WhatsApp OTP sent to "+phone+". Enter the 6-digit code to complete registration.":"Email OTP sent to "+f.email.trim()+". Enter the 6-digit code to complete registration.");
   setBusy(false);
 }
 async function verifyRegistration(e){
   e.preventDefault();const token=otp.trim();
   if(!/^\d{6}$/.test(token)){setMsg("Please enter the 6-digit OTP.");return}
   setBusy(true);setMsg(verifyMethod==="mobile"?"Verifying mobile number…":"Verifying email address…");
   const{data,error}=verifyMethod==="mobile"
     ?await supabase.auth.verifyOtp({phone:registeredPhone,token,type:"sms"})
     :await supabase.auth.verifyOtp({email:f.email.trim().toLowerCase(),token,type:"signup"});
   if(error){setMsg(error.message||"Invalid or expired OTP.");setBusy(false);return}
   const user=data?.user||pendingUser;
   if(!user){setMsg("Verification succeeded, but the account session could not be loaded. Please sign in.");setBusy(false);return}
   const{error:profileError}=await supabase.rpc("link_verified_customer",{p_name:(f.first_name.trim()+" "+f.last_name.trim()).trim(),p_first_name:f.first_name.trim(),p_last_name:f.last_name.trim(),p_email:f.email.trim().toLowerCase()||null,p_phone:registeredPhone||null,p_address:f.address.trim(),p_city:f.city.trim(),p_district:f.district.trim(),p_province:f.province.trim(),p_postal_code:f.postal_code.trim()||null});
   if(profileError){setMsg(profileError.message);setBusy(false);return}
   setMsg((verifyMethod==="mobile"?"Mobile number":"Email address")+" verified. Your account is ready.");
   await offerPasskeyPrompt(user.id);location.href="account/";
 }
 async function resendOtp(){
   if(busy)return;
   setBusy(true);setMsg("Sending a new OTP…");
   const{error}=verifyMethod==="mobile"
     ?await supabase.auth.resend({type:"sms",phone:registeredPhone,options:{channel:"whatsapp"}})
     :await supabase.auth.resend({type:"signup",email:f.email.trim().toLowerCase()});
   setMsg(error?error.message:verifyMethod==="mobile"?"A new OTP has been sent to "+registeredPhone+".":"A new OTP has been sent to "+f.email.trim()+".");
   setBusy(false);
 }
 if(otpStep)return <AuthLayout title={verifyMethod==="mobile"?"Verify Mobile Number":"Verify Email Address"}><p className="auth-intro">Enter the 6-digit OTP sent to <b>{verifyMethod==="mobile"?registeredPhone:f.email.trim()}</b> to finish creating your account.</p><form onSubmit={verifyRegistration}><label className="field">OTP <span className="required-star">*</span><input type="text" value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,"").slice(0,6))} inputMode="numeric" autoComplete="one-time-code" maxLength="6" required autoFocus/></label><button className="btn" disabled={busy}>{busy?"Verifying…":"Verify & Create Account"}</button>{msg&&<div className={msg.toLowerCase().includes("verified")?"message success":"message error"}>{msg}</div>}</form><div className="auth-links"><button type="button" className="text-button" onClick={resendOtp} disabled={busy}>Resend OTP</button> · <button type="button" className="text-button" onClick={()=>{supabase.auth.signOut();setOtpStep(false);setMsg("");}}>Change Details</button></div></AuthLayout>;
 return <AuthLayout title="Create Account"><p className="auth-intro">Create your account and verify either your email address or mobile number with a one-time code.</p><div className="login-method-switch" role="group" aria-label="Verification method"><button type="button" className={verifyMethod==="email"?"active":""} onClick={()=>{setVerifyMethod("email");setMsg("");}}>Email OTP</button><button type="button" className={verifyMethod==="mobile"?"active":""} onClick={()=>{setVerifyMethod("mobile");setMsg("");}}>Mobile OTP</button></div><form onSubmit={createAccount}>
 <label className="field">First Name <span className="required-star">*</span><input name="first_name" type="text" value={f.first_name} onChange={change} required autoComplete="given-name"/></label>
 <label className="field">Last Name <span className="required-star">*</span><input name="last_name" type="text" value={f.last_name} onChange={change} required autoComplete="family-name"/></label>
 <label className="field">Email Address {verifyMethod==="email"?<span className="required-star">*</span>:<span className="optional-label">(Optional)</span>}<input name="email" type="email" value={f.email} onChange={change} autoComplete="email" required={verifyMethod==="email"}/></label>
 <label className="field">Password <span className="required-star">*</span><input name="password" type="password" value={f.password} onChange={change} required autoComplete="new-password"/></label>
 <label className="field">Confirm Password <span className="required-star">*</span><input name="confirm" type="password" value={f.confirm} onChange={change} required autoComplete="new-password"/></label>
 <label className="field">Mobile Number <span className="required-star">*</span><div className="phone-input-wrap"><span className="phone-country-code">+977</span><input name="phone" type="tel" value={f.phone} onChange={change} required autoComplete="tel-national" inputMode="numeric" maxLength="10" placeholder="10-digit mobile number"/></div></label>
 <label className="field">Delivery Address <span className="required-star">*</span><textarea name="address" rows="3" value={f.address} onChange={change} required/></label>
 <label className="field">Province <span className="required-star">*</span><select name="province" value={f.province} onChange={change} required><option value="">Select Province</option>{NEPAL_PROVINCES.map(p=><option key={p.name} value={p.name}>{p.name}</option>)}</select></label>
 <label className="field">District <span className="required-star">*</span><select name="district" value={f.district} onChange={change} required disabled={!f.province}><option value="">{f.province?"Select District":"Select Province First"}</option>{provinceDistricts(f.province).map(d=><option key={d} value={d}>{d}</option>)}</select></label>
 <label className="field">City <span className="required-star">*</span><input name="city" value={f.city} onChange={change} required/></label>
 <label className="field">Postal Code <span className="optional-label">(Optional)</span><input name="postal_code" value={f.postal_code} onChange={change} inputMode="numeric" autoComplete="postal-code"/></label>
 <button className="btn" disabled={busy}>{busy?"Sending OTP…":verifyMethod==="mobile"?"Continue & Verify Mobile":"Continue & Verify Email"}</button>{msg&&<div className="message error">{msg}</div>}</form><div className="auth-google"><button type="button" className="google-auth-button" onClick={googleSignIn} disabled={busy}><span className="google-g" aria-hidden="true">G</span>Continue with Google</button></div><div className="auth-links">Already have an account? <a href="login.html">Sign in</a></div></AuthLayout>
}
function Account(){
 const[passkeyBusy,setPasskeyBusy]=useState(false),[passkeyMsg,setPasskeyMsg]=useState(""),[passkeys,setPasskeys]=useState([]),[passkeyChecking,setPasskeyChecking]=useState(true);
 const currentPath=location.pathname.replace(/\/+$/,"");
 const ordersOnly=document.body?.dataset.page==="orders"||currentPath.endsWith("/orders")||currentPath.endsWith("/orders/")||new URLSearchParams(location.search).get("page")==="orders";
 const[session,setSession]=useState(null),[profile,setProfile]=useState(null),[googleLinkBusy,setGoogleLinkBusy]=useState(false),[orders,setOrders]=useState([]),[orderTab,setOrderTab]=useState("active"),[selectedOrder,setSelectedOrder]=useState(null),[selectedOrderBusy,setSelectedOrderBusy]=useState(false),[editing,setEditing]=useState(false),[msg,setMsg]=useState(""),[busy,setBusy]=useState(true),[actionBusy,setActionBusy]=useState(""),[ordersLoadingMore,setOrdersLoadingMore]=useState(false),[ordersHasMore,setOrdersHasMore]=useState(false),[ncmBranches,setNcmBranches]=useState([]),[ncmBranchBusy,setNcmBranchBusy]=useState(false),[trackingToShow,setTrackingToShow]=useState("");
 useEffect(()=>{(async()=>{const{data}=await supabase.auth.getSession();if(!data.session){location.href="login.html";return}setSession(data.session);try{const{data:keys,error:keyError}=await supabase.auth.passkey.list();if(keyError)throw keyError;setPasskeys(Array.isArray(keys)?keys:[])}catch(e){console.warn("Unable to check registered passkeys",e)}finally{setPasskeyChecking(false)}if(new URLSearchParams(location.search).get("google_link")==="1")setMsg("Google linking completed. Check the account details below to confirm the linked identity.");const{data:p,error:profileError}=await supabase.from("customers").select("id,auth_user_id,name,first_name,last_name,email,phone,address,city,district,province,postal_code,ncm_destination_branch,is_active").eq("auth_user_id",data.session.user.id).maybeSingle();if(profileError)throw profileError;setProfile(p||null);if(p&&ordersOnly){const pageSize=25;const{data:o}=await supabase.from("orders").select("id,order_number,total,payment_method,payment_status,order_status,shipping_address,city,district,province,postal_code,created_at,updated_at,ncm_order_id,ncm_status,ncm_tracking_id,ncm_delivery_type,ncm_source_branch,ncm_destination_branch,cancellation_status,cancellation_reason,cancellation_requested_at,cancellation_reviewed_at,cancellation_admin_note,order_items(quantity),invoice_number,invoice_issued_at,invoice_visible_at,invoice_data").eq("customer_id",p.id).order("created_at",{ascending:false}).range(0,pageSize-1);const rows=o||[];setOrders(rows);setOrdersHasMore(rows.length===pageSize)}})().catch(e=>setMsg(e?.message||"Unable to load your account.")).finally(()=>setBusy(false))},[]);
 useEffect(()=>{
  if(!ordersOnly||!profile?.id)return;
  const channel=supabase.channel("customer-orders-"+profile.id)
    .on("postgres_changes",{event:"UPDATE",schema:"public",table:"orders",filter:"customer_id=eq."+profile.id},payload=>{
      const next=payload.new;
      setOrders(prev=>prev.map(o=>o.id===next.id?{...o,...next}:o));
      setSelectedOrder(prev=>prev?.id===next.id?{...prev,...next}:prev);
    })
    .subscribe();
  return()=>{supabase.removeChannel(channel)};
 },[ordersOnly,profile?.id]);
 useEffect(()=>{if(!editing||ordersOnly||ncmBranches.length)return;(async()=>{try{setNcmBranchBusy(true);const bs=await getNcmBranches();setNcmBranches(bs);if(profile&&!profile.ncm_destination_branch){const matched=matchNcmBranch(bs,profile.city,profile.district);if(matched)setProfile(p=>p?{...p,ncm_destination_branch:matched}:p)}}catch{}finally{setNcmBranchBusy(false)}})()},[editing,ordersOnly,ncmBranches.length,profile]);
 async function loadMoreOrders(){if(!profile?.id||ordersLoadingMore||!ordersHasMore)return;setOrdersLoadingMore(true);try{const pageSize=25;const{data:o}=await supabase.from("orders").select("id,order_number,total,payment_method,payment_status,order_status,shipping_address,city,district,province,postal_code,created_at,updated_at,ncm_order_id,ncm_status,ncm_tracking_id,ncm_delivery_type,ncm_source_branch,ncm_destination_branch,cancellation_status,cancellation_reason,cancellation_requested_at,cancellation_reviewed_at,cancellation_admin_note,order_items(quantity),invoice_number,invoice_issued_at,invoice_visible_at,invoice_data").eq("customer_id",profile.id).order("created_at",{ascending:false}).range(orders.length,orders.length+pageSize-1);const rows=o||[];setOrders(prev=>[...prev,...rows]);setOrdersHasMore(rows.length===pageSize)}finally{setOrdersLoadingMore(false)}}
 async function save(e){e.preventDefault();if(!profile.first_name?.trim()||!profile.last_name?.trim()||!profile.phone?.trim()||!profile.address?.trim()||!profile.city?.trim()||!profile.district?.trim()||!profile.province?.trim()){setMsg("Please fill in all required fields.");return}setMsg("Saving…");const{data,error}=await supabase.from("customers").update({name:(profile.first_name.trim()+" "+profile.last_name.trim()).trim(),first_name:profile.first_name.trim(),last_name:profile.last_name.trim(),phone:profile.phone.trim(),address:profile.address.trim(),city:profile.city.trim(),district:profile.district.trim(),province:canonicalProvince(profile.province),postal_code:profile.postal_code?.trim()||null,ncm_destination_branch:profile.ncm_destination_branch?.trim()||null,updated_at:new Date().toISOString()}).eq("auth_user_id",session.user.id).select().maybeSingle();if(error){setMsg(error.message);return}if(data)setProfile(data);setEditing(false);setMsg("Account details saved successfully.")}
 async function logout(){await supabase.auth.signOut();location.href="login.html"}
 const handleCancellation=async(o,action)=>{
 const labels={cancel:"Cancel this order?",request_cancellation:"Request cancellation for this order?"};
 if(!confirm(labels[action]||"Continue?"))return;
 let reason=null;
 if(action==="request_cancellation"){reason=prompt("Reason for cancellation (optional):","");if(reason===null)return}
 setActionBusy(o.id);setMsg("");
 try{
   const{data,error}=await supabase.rpc("handle_order_cancellation",{p_order_id:o.id,p_action:action,p_reason:reason||null,p_admin_note:null});
   if(error)throw error;
   if(data?.status==="cancelled")setMsg("Order "+(o.order_number||"")+" has been cancelled.");
   else setMsg("Cancellation request submitted for "+(o.order_number||"")+".");
   const{data:updated,error:oe}=await supabase.from("orders").select("id,order_number,total,payment_method,payment_status,order_status,shipping_address,city,district,province,postal_code,created_at,updated_at,ncm_order_id,ncm_status,ncm_tracking_id,ncm_delivery_type,ncm_source_branch,ncm_destination_branch,cancellation_status,cancellation_reason,cancellation_requested_at,cancellation_reviewed_at,cancellation_admin_note,order_items(product_name,product_code,size,color,quantity,unit_price,total_price),invoice_number,invoice_issued_at,invoice_visible_at,invoice_data").eq("id",o.id).single();
   if(!oe&&updated){setOrders(prev=>prev.map(x=>x.id===o.id?updated:x));setSelectedOrder(updated)}
 }catch(e){setMsg("Unable to update cancellation. "+(e?.message||"Please try again."))}
 finally{setActionBusy("")}
};
const openOrder=async(o)=>{setSelectedOrderBusy(true);try{const{data,error}=await supabase.from("orders").select("id,order_number,total,payment_method,payment_status,order_status,shipping_address,city,district,province,postal_code,created_at,updated_at,ncm_order_id,ncm_status,ncm_tracking_id,ncm_delivery_type,ncm_source_branch,ncm_destination_branch,cancellation_status,cancellation_reason,cancellation_requested_at,cancellation_reviewed_at,cancellation_admin_note,order_items(product_name,product_code,size,color,quantity,unit_price,total_price),invoice_number,invoice_issued_at,invoice_visible_at,invoice_data").eq("id",o.id).single();if(error)throw error;setSelectedOrder(data||o)}catch(e){setMsg("Unable to load order details. "+(e?.message||"Please try again."))}finally{setSelectedOrderBusy(false)}};
 const activeOrders=orders.filter(o=>o.order_status!=="cancelled");
 const cancelledOrders=orders.filter(o=>o.order_status==="cancelled");
 const displayedOrders=orderTab==="cancelled"?cancelledOrders:activeOrders;
 const closeOrder=()=>setSelectedOrder(null);
 if(busy)return <><Header/><main className="page"><section className="account-card"><div className="product-loading">Loading account…</div></section></main><Footer/></>;
 if(!profile)return <><Header/><main className="page"><section className="account-card"><h1>Welcome, Customer</h1><div className="message error">Your login is active, but your customer profile could not be found.</div>{!ordersOnly&&<button className="btn secondary" onClick={logout}>Logout</button>}</section></main><Footer/></>;
 return <><Header/><main className="page"><section className="account-card"><h1>Welcome, {profile.name||"Customer"}</h1>
 {!ordersOnly&&<div className="account-google-link account-security-card"><h2>Passkey Sign-In</h2><p>Manage the passkeys saved to your account. Add more than one for backup, or remove a device you no longer use.</p>{passkeyChecking?<p className="passkey-empty">Checking your saved passkeys…</p>:passkeys.length>0?<div className="passkey-list">{passkeys.map((key,index)=><div className="passkey-row" key={key.id}><div className="passkey-details"><strong>{key.friendly_name||"Passkey "+(index+1)}</strong><span>{key.created_at?"Added "+new Date(key.created_at).toLocaleDateString():"Registered passkey"}</span></div><button className="passkey-delete-button" type="button" disabled={passkeyBusy} onClick={async()=>{if(!window.confirm("Delete this passkey? You may no longer be able to sign in with the device that uses it."))return;setPasskeyBusy(true);setPasskeyMsg("");try{const{error}=await supabase.auth.passkey.delete({passkeyId:key.id});if(error)throw error;setPasskeys(prev=>prev.filter(item=>item.id!==key.id));setPasskeyMsg("Passkey deleted.")}catch(e){setPasskeyMsg(e?.message||"Could not delete passkey.")}finally{setPasskeyBusy(false)}}}>Delete</button></div>)}</div>:<p className="passkey-empty">No passkeys are currently registered.</p>}<button className="btn secondary passkey-add-button" type="button" disabled={passkeyBusy||passkeyChecking} onClick={async()=>{setPasskeyBusy(true);setPasskeyMsg("Starting passkey setup…");try{const{data,error}=await supabase.auth.registerPasskey();if(error)throw error;if(data)setPasskeys(prev=>[...prev.filter(item=>item.id!==data.id),data]);else{const{data:keys,error:listError}=await supabase.auth.passkey.list();if(listError)throw listError;setPasskeys(Array.isArray(keys)?keys:[])}setPasskeyMsg("Passkey added successfully.")}catch(e){setPasskeyMsg(e?.message||"Passkey setup failed.")}finally{setPasskeyBusy(false)}}}>{passkeyBusy?"Working…":"Add Another Passkey"}</button>{passkeyMsg&&<div className="message">{passkeyMsg}</div>}</div>}
 {!ordersOnly&&<div className="account-google-link account-google-card"><h2>Google Sign-In</h2><p>{session?.user?.identities?.some(i=>i.provider==="google")?"Google is linked to this account.":"Connect Google to this existing account. You must be signed in here first."}</p><button className="btn secondary account-google-button" type="button" disabled={googleLinkBusy||session?.user?.identities?.some(i=>i.provider==="google")} onClick={async()=>{setGoogleLinkBusy(true);setMsg("Connecting to Google…");const{error}=await supabase.auth.linkIdentity({provider:"google",options:{redirectTo:location.origin+"/account/?google_link=1"}});if(error){setMsg(error.message);setGoogleLinkBusy(false)}}}>{googleLinkBusy?"Connecting…":session?.user?.identities?.some(i=>i.provider==="google")?"Google Linked":"Link Google"}</button>{msg&&<div className="message">{msg}</div>}</div>}
 {!ordersOnly&&<> <h2>My Profile</h2>{editing?<div className="account-edit-card"><div className="edit-card-header"><h2>Edit Account Details</h2><button className="secondary" type="button" onClick={()=>{setEditing(false);setMsg("")}}>Cancel</button></div><form className="profile-form" onSubmit={save}>
 <label className="field">First Name <span className="required-star">*</span><input value={profile.first_name||""} onChange={e=>setProfile({...profile,first_name:e.target.value})} required autoComplete="given-name"/></label>
 <label className="field">Last Name <span className="required-star">*</span><input value={profile.last_name||""} onChange={e=>setProfile({...profile,last_name:e.target.value})} required autoComplete="family-name"/></label>
 <label className="field">Email Address <span className="required-star">*</span><input value={profile.email||session.user.email||""} readOnly required/></label>
 <label className="field">Phone Number <span className="required-star">*</span><input value={profile.phone||""} onChange={e=>setProfile({...profile,phone:e.target.value})} required/></label>
 <label className="field">Delivery Address <span className="required-star">*</span><textarea rows="3" value={profile.address||""} onChange={e=>setProfile({...profile,address:e.target.value})} required/></label>
 <label className="field">Province <span className="required-star">*</span><select value={canonicalProvince(profile.province)} onChange={e=>setProfile({...profile,province:e.target.value,district:""})} required><option value="">Select Province</option>{NEPAL_PROVINCES.map(p=><option key={p.name} value={p.name}>{p.name}</option>)}</select></label>
 <label className="field">District <span className="required-star">*</span><select value={profile.district||""} onChange={e=>setProfile({...profile,district:e.target.value})} required disabled={!canonicalProvince(profile.province)}><option value="">{canonicalProvince(profile.province)?"Select District":"Select Province First"}</option>{provinceDistricts(canonicalProvince(profile.province)).map(d=><option key={d} value={d}>{d}</option>)}</select></label>
 <label className="field">City <span className="required-star">*</span><input value={profile.city||""} onChange={e=>setProfile({...profile,city:e.target.value})} required/></label>
 <label className="field">Postal Code <span className="optional-label">(Optional)</span><input value={profile.postal_code||""} onChange={e=>setProfile({...profile,postal_code:e.target.value})} inputMode="numeric" autoComplete="postal-code"/></label>
 <label className="field">Nearest NCM Branch <span className="optional-label">(Recommended)</span><select value={profile.ncm_destination_branch||""} onChange={e=>setProfile({...profile,ncm_destination_branch:e.target.value})} disabled={ncmBranchBusy}><option value="">{ncmBranchBusy?"Finding branch…":"Select NCM branch"}</option>{ncmBranches.map(b=><option key={b.name} value={b.name}>{b.name}{b.district_name?" — "+b.district_name:""}</option>)}</select><small className="form-note">Automatically matched from your city/district when possible. If no nearby match is found, choose the branch you use for delivery.</small></label>
 <button className="btn" disabled={msg==="Saving…"}>Save Account Details</button>{msg&&<div className="message">{msg}</div>}</form></div>:<><div className="profile-grid">{[["Name",profile.name],["Email",profile.email||session.user.email],["Phone",profile.phone],["Address",profile.address],["City",profile.city],["District",profile.district],["Province",profile.province],["Postal Code",profile.postal_code],["NCM Delivery Branch",profile.ncm_destination_branch]].map(([l,v])=><div className="profile-item" key={l}><b>{l}</b><span>{v||"—"}</span></div>)}</div>
 <div className="account-edit-trigger"><button className="btn secondary" type="button" onClick={()=>{setEditing(true);setMsg("")}}>Edit Details</button></div></>}
 </>}
 {ordersOnly&&<> <div className="orders-section"><div className="section-heading"><div><h2>{orderTab==="cancelled"?"Cancelled Orders":"My Orders"}</h2><p>View your orders and delivery status.</p></div></div><div className="orders-tabs" role="tablist"><button type="button" className={orderTab==="active"?"orders-tab active":"orders-tab"} onClick={()=>setOrderTab("active")}>My Orders ({activeOrders.length})</button><button type="button" className={orderTab==="cancelled"?"orders-tab active":"orders-tab"} onClick={()=>setOrderTab("cancelled")}>Cancelled Orders ({cancelledOrders.length})</button></div>
 {displayedOrders.length?displayedOrders.map(o=><article className="order-card" key={o.id}><div className="order-head"><div><strong>{o.order_number||"Order"}</strong><small>{new Date(o.created_at).toLocaleString()}</small></div><span className="order-status-badge">{o.order_status||"pending"}</span></div><div className="order-summary-grid"><div><b>Total</b><span>NPR {Number(o.total||0).toLocaleString("en-IN")}</span></div><div><b>Payment</b><span>{o.payment_method||"—"} · {o.payment_status||"—"}</span></div><div><b>Items</b><span>{(o.order_items||[]).reduce((n,i)=>n+Number(i.quantity||0),0)||"—"}</span></div><div><b>Delivery</b><span>{o.ncm_status||o.order_status||"Pending"}</span></div></div><div className="order-actions"><div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"nowrap",width:"100%"}}><button className="btn secondary" style={{flex:"1 1 auto"}} type="button" onClick={()=>openOrder(o)} disabled={selectedOrderBusy}>{selectedOrderBusy?"Loading…":"View Order Details"}</button>{o.ncm_tracking_id&&<button className="btn" style={{flex:"0 0 auto"}} type="button" onClick={()=>setTrackingToShow(String(o.ncm_tracking_id))}>Track Package</button>}</div>{o.order_status==="pending"&&o.cancellation_status==="none"&&<button className="btn danger" type="button" disabled={actionBusy===o.id} onClick={()=>handleCancellation(o,"cancel")}>{actionBusy===o.id?"Cancelling…":"Cancel Order"}</button>}{o.order_status==="confirmed"&&o.cancellation_status==="none"&&<button className="btn secondary" type="button" disabled={actionBusy===o.id} onClick={()=>handleCancellation(o,"request_cancellation")}>{actionBusy===o.id?"Submitting…":"Request Cancellation"}</button>}{o.order_status==="confirmed"&&o.cancellation_status==="requested"&&<span className="cancellation-pending">Cancellation Requested</span>}{o.order_status==="confirmed"&&o.cancellation_status==="rejected"&&<span className="cancellation-rejected">Cancellation Request Rejected</span>}</div></article>):<p>{orderTab==="cancelled"?"No cancelled orders.":"No active orders."}</p>}{ordersHasMore&&<div className="catalog-load-more"><button className="secondary-button" type="button" onClick={loadMoreOrders} disabled={ordersLoadingMore}>{ordersLoadingMore?"Loading…":"Load More Orders"}</button></div>}</div>
 {trackingToShow&&<div className="order-details-overlay tracking-overlay" role="dialog" aria-modal="true"><div className="order-details-modal" style={{maxWidth:480}}><div className="order-details-header"><div><h2>Track Your Order</h2><p>Your NCM tracking number</p></div><button className="secondary" type="button" onClick={()=>setTrackingToShow("")}>Close</button></div><div className="tracking-box"><div><b>Tracking Number</b><span style={{fontSize:20,fontWeight:700,letterSpacing:1}}>{trackingToShow}</span></div><button className="btn" type="button" onClick={async()=>{try{await navigator.clipboard.writeText(trackingToShow)}catch{} }}>Copy Tracking ID</button><button className="btn secondary" type="button" onClick={()=>{window.open("https://portal.nepalcanmove.com/track/","_blank","noopener,noreferrer")}}>Open NCM Tracking</button></div></div></div>}
 {selectedOrder&&<div className="order-details-overlay" role="dialog" aria-modal="true"><div className="order-details-modal"><div className="order-details-header"><div><h2>Order {selectedOrder.order_number||""}</h2><p>{new Date(selectedOrder.created_at).toLocaleString()}</p></div><button className="secondary" type="button" onClick={closeOrder}>Close</button></div><div className="order-detail-status"><div className="order-detail-status-item"><small>Order Status</small><span className="order-status-badge">{selectedOrder.order_status||"pending"}</span></div>{selectedOrder.ncm_status&&<div className="order-detail-status-item"><small>NCM Shipment</small><span className="tracking-status">{selectedOrder.ncm_status}</span></div>}{selectedOrder.cancellation_status==="requested"&&<div className="order-detail-status-item"><small>Cancellation</small><span className="tracking-status">Cancellation Requested</span></div>}</div><h3>Items</h3><div className="order-detail-items">{(selectedOrder.order_items||[]).map((i,n)=><div className="order-detail-item" key={n}><div><strong>{i.product_name||"Product"}</strong><small>{[i.product_code,i.color,i.size].filter(Boolean).join(" · ")}</small></div><div><span>{i.quantity} × NPR {Number(i.unit_price||0).toLocaleString("en-IN")}</span><strong>NPR {Number(i.total_price||0).toLocaleString("en-IN")}</strong></div></div>)}</div><div className="order-detail-total"><span>Total</span><strong>NPR {Number(selectedOrder.total||0).toLocaleString("en-IN")}</strong></div><h3>Delivery Details</h3><div className="order-detail-address">{[selectedOrder.shipping_address,selectedOrder.city,selectedOrder.district,selectedOrder.province,selectedOrder.postal_code].filter(Boolean).map((x,i)=><span key={i}>{x}</span>)}{selectedOrder.ncm_destination_branch&&<span><b>NCM Delivery Branch:</b> {selectedOrder.ncm_destination_branch}</span>}</div><div className="order-detail-payment"><span>Payment Method: {selectedOrder.payment_method||"—"}</span><span>Payment Status: {selectedOrder.payment_status||"—"}</span></div>{selectedOrder.cancellation_reason&&<div className="cancellation-note"><b>Cancellation reason:</b> {selectedOrder.cancellation_reason}</div>}{selectedOrder.cancellation_status==="rejected"&&selectedOrder.cancellation_admin_note&&<div className="cancellation-note"><b>Admin response:</b> {selectedOrder.cancellation_admin_note}</div>}{["shipped","delivered"].includes(String(selectedOrder.order_status||"").toLowerCase())&&selectedOrder.invoice_data&&<div className="invoice-available-box"><div><b>Invoice</b><span>{selectedOrder.invoice_number||"Invoice available"}</span></div><button className="btn" type="button" onClick={()=>{closeOrder();openCustomerInvoice(selectedOrder)}}>Download Invoice</button></div>}{selectedOrder.ncm_tracking_id&&!/^(cancelled|canceled)$/i.test(String(selectedOrder.ncm_status||"").trim())&&<div className="tracking-box"><div><b>Tracking Number</b><span>{selectedOrder.ncm_tracking_id}</span></div><button className="btn" type="button" onClick={()=>{setSelectedOrder(null);setTrackingToShow(String(selectedOrder.ncm_tracking_id))}}>Track Package</button></div>}</div></div>}
 </>}
 {!ordersOnly&&<button className="btn secondary" onClick={logout}>Logout</button>}
 </section></main><Footer/></>
}
function Home(){return <><Header/><main><section className="hero"><div className="hero-content"><p className="eyebrow">SURU COLLECTION</p><h1>More Than Fashion.<br/><em>It's a Feeling.</em></h1><p>Discover thoughtfully selected traditional and ethnic wear designed to make every occasion feel special.</p><a className="hero-button" href="products.html">Explore Products</a></div></section><section id="collection" className="section"><div className="section-heading"><p className="eyebrow">OUR COLLECTION</p><h2>Made for Every Celebration</h2><p>Explore timeless silhouettes, festive favourites and elegant everyday styles.</p></div><div className="collection-grid">{cats.map(([image,name,description])=><CollectionCard key={name} image={image} name={name} description={description}/>)}</div></section><section className="section home-products-section featured-products-section"><div className="section-heading"><p className="eyebrow">HANDPICKED FOR YOU</p><h2>Featured Products</h2><p>Explore the pieces selected as our featured favourites.</p></div><ProductsGrid featured limit={12}/><div className="featured-view-all"><a className="secondary-button" href="products.html?featured=true">View All Featured Products</a></div></section><section className="section home-products-section recent-products-section"><div className="section-heading"><p className="eyebrow">JUST ARRIVED</p><h2>Recently Added</h2><p>Discover the latest additions to Suru Collection.</p></div><ProductsGrid limit={12}/></section></main><Footer/></>}
function About(){return <><Header/><main><Hero eyebrow="ABOUT SURU COLLECTION" title="Festive fashion, for every corner of Nepal." text="A passion-led fashion destination bringing beautiful festive collections closer to you, wherever you are in Nepal."/><section className="section story-section about-story"><div className="story-grid"><div className="story-image"><img src="/assets/story.jpg" alt="Suru Collection festive fashion"/></div><div className="story-content"><p className="eyebrow">OUR STORY</p><h2>A shared dream, inspired by a passion for fashion.</h2><p>Suru Collection began with Suruchi Sahani’s deep passion for fashion and her love for discovering beautiful styles. Shortly after their wedding in February 2026, Suruchi and her husband, Roshankumar Sahani, turned a shared idea into a plan to make festive fashion more accessible across Nepal.</p><p>That dream took shape in October 2026. Built as a husband-and-wife venture, Suru Collection is focused on bringing together special festive pieces that help customers celebrate their moments with confidence and style.</p><p className="story-signature">With love, Suruchi Sahani &amp; Roshankumar Sahani</p></div></div></section><section className="section about-purpose"><div className="about-section-heading"><p className="eyebrow">WHY WE’RE HERE</p><h2>Our purpose, in every collection.</h2><p>Fashion should feel special and be within reach, wherever celebration happens.</p></div><div className="about-purpose-grid"><article className="about-purpose-card"><span className="about-card-mark">✦</span><p className="eyebrow">OUR MISSION</p><h3>Festive fashion within everyone’s reach.</h3><p>To bring the best festive collections to every corner of Nepal, making it easier for people everywhere to find outfits for their most meaningful celebrations.</p></article><article className="about-purpose-card"><span className="about-card-mark">✧</span><p className="eyebrow">OUR VISION</p><h3>A trusted name for festive style.</h3><p>To become Nepal’s best-selling e-commerce destination for festive fashion, and grow into a trusted online fashion destination across the country as we expand into new categories.</p></article></div></section><section className="section about-special"><div className="about-special-copy"><p className="eyebrow">THE SURU DIFFERENCE</p><h2>Collections chosen for the moments that matter.</h2><p>Festivals and celebrations deserve something memorable. That is why festive fashion is at the heart of Suru Collection. We focus on bringing together beautiful, occasion-ready collections so customers can explore styles for their celebrations from the comfort of home.</p></div><div className="about-special-points"><div><span>01</span><p><strong>Festive-first selection</strong><br/>Collections centered on the joy and spirit of festive seasons.</p></div><div><span>02</span><p><strong>Reach across Nepal</strong><br/>Online shopping designed to bring our collections closer to customers nationwide.</p></div><div><span>03</span><p><strong>A growing destination</strong><br/>A thoughtful start, with room to discover new styles and categories over time.</p></div></div></section><section className="section business-information" id="business-information"><div className="about-section-heading"><p className="eyebrow">OFFICIAL BUSINESS DETAILS</p><h2>Business Information</h2><p>For transparency and customer confidence, our business registration and contact details are listed below.</p></div><div className="business-information-content"><dl><div><dt>Registered Business Name</dt><dd>Suru Collection</dd></div><div><dt>Business Registration Number</dt><dd>16104/234</dd></div><div><dt>Registration Authority</dt><dd>CSIO, Gaur, Rautahat</dd></div><div><dt>PAN Number</dt><dd>625070013</dd></div><div><dt>Business Address</dt><dd>Gaur Tikuliya Road, Gaur-4, Rautahat, Madhesh Pradesh, Nepal</dd></div></dl><p className="business-information-note">For customer complaints and grievances, please contact our designated complaint-handling officer through the Contact Us page.</p><a className="coming-soon-link" href="/contact.html">Customer Support <span aria-hidden="true">→</span></a></div></section><section className="about-closing"><p className="eyebrow">CELEBRATE YOUR WAY</p><h2>Every celebration has a look.<br/>Let’s find yours.</h2><p>Explore the collection and discover festive fashion from Suru Collection.</p><a className="coming-soon-link" href="products.html">Explore Collections <span aria-hidden="true">→</span></a></section></main><Footer/></>}
