 const loadInvoiceSettings=async()=>{const{data,error}=await supabase.from("invoice_settings").select("*").eq("id",true).maybeSingle();if(error)setMessage(error.message);else if(data)setInvoiceSettings(data)};
 const saveInvoiceSettings=async(e)=>{e?.preventDefault();setInvoiceSettingsBusy(true);try{const payload={...invoiceSettings,id:true,business_name:String(invoiceSettings.business_name||"Suru Collection").trim(),business_address:String(invoiceSettings.business_address||"").trim()||null,business_phone:String(invoiceSettings.business_phone||"").trim()||null,business_email:String(invoiceSettings.business_email||"").trim()||null,business_pan:String(invoiceSettings.business_pan||"").trim()||null,vat_registered:!!invoiceSettings.vat_registered,vat_rate:Number(invoiceSettings.vat_rate||13),invoice_prefix:String(invoiceSettings.invoice_prefix||"SC-INV").trim()||"SC-INV",seller_signature:String(invoiceSettings.seller_signature||"").trim()||null};const{data,error}=await supabase.from("invoice_settings").upsert(payload,{onConflict:"id"}).select().single();if(error)throw error;if(data)setInvoiceSettings(data);setMessage("Invoice settings saved successfully.")}catch(e){setMessage("Invoice settings: "+(e?.message||"Unable to save."))}finally{setInvoiceSettingsBusy(false)}};
